using System;
using System.Collections.Generic;
using TamTam.Core;

namespace TamTam.Evolution
{
    // JSON model of Assets/TamTam/Data/Evolution (generated by tools/export-unity.ts from the web prototype).
    // JsonUtility-friendly: plain [Serializable] classes and arrays only.

    [Serializable] public class PaintJson { public string kind, token, hex; public float alpha = 1; public string[] stops; public float fx, fy, tx, ty; }
    [Serializable] public class PartJson
    {
        public string id, bone, d; public float z; public PaintJson fill, stroke; public float strokeWidth, blur;
        public bool emissive, sheen; public string faceSlot; public string[] faceStates; public int[] tiers;
    }
    [Serializable] public class BoneJson { public string id, parent; public float x, y, rot; }
    [Serializable] public class SecondaryJson { public string bone, driver; public float lag, gain, velocityGain, swayAmp, swayFreq, flickerAmp, flickerFreq; }
    [Serializable] public class RigJson { public string id; public BoneJson[] bones; public PartJson[] parts; public SecondaryJson[] secondary; public string breathBone; public string[] eyeBones; }
    [Serializable] public class LibraryEntry { public string slot, label, family; public int variant; public bool @float; public PartJson[] parts; }
    [Serializable] public class FamilyJson
    {
        public string id, name, element, accent, eye, glow, particleShape, particleColor, suffix, skill, locomotion;
        public string[] bases, prefixes;
    }
    [Serializable] public class MotionJson
    {
        public float bounce, sway, jitter, tail, tilt, breath, tempo = 1, lift, wave, flap, shake, speed = 1;
        public bool @float; public string gait;
    }
    [Serializable] public class EyeJson { public float x, y, r; public string lid; }
    [Serializable] public class StarterJson
    {
        public string id, family, species, title, favoriteFood, art; public int variant; public string[] traits, lines;
        public EyeJson eye; public MotionJson motion; public GenomeJson genome;
    }
    [Serializable] public class StageMotionJson { public string family, stage, gait; public MotionJson motion; }
    [Serializable] public class AssemblyJson { public string[] order; public float floatBodyLift; public string floatBone; }
    [Serializable] public class CatalogJson
    {
        public int version; public string note; public double combinations;
        public FamilyJson[] families; public string[] eyeStyles, patterns, mutations;
        public RigJson skeleton; public LibraryEntry[] library; public AssemblyJson assembly;
        public StarterJson[] starters; public StageMotionJson[] motions;
    }
    [Serializable] public class GenomeJson
    {
        [Serializable] public class Slots { public string body, head, legs, tail, back; }
        [Serializable] public class Variants { public int body, head, legs, tail, back; }
        [Serializable] public class Pal { public string @base; public int shade; public string accent; }
        public Slots parts; public Variants variant; public string eyes, pattern, mutation; public Pal palette;

        public Genome ToGenome()
        {
            Family F(string s) => (Family)Enum.Parse(typeof(Family), s);
            var g = new Genome { eyes = eyes, pattern = pattern, mutation = mutation, paletteBase = F(palette.@base), shade = palette.shade, paletteAccent = F(palette.accent) };
            g.parts = new[] { F(parts.body), F(parts.head), F(parts.legs), F(parts.tail), F(parts.back) };
            g.variant = new[] { variant.body, variant.head, variant.legs, variant.tail, variant.back };
            return g;
        }
    }
    [Serializable] public class PaletteJson { public string @base, accent, eye, glow; }
    [Serializable] public class FormJson { public string key, name; public GenomeJson genome; public bool @float; public PaletteJson palette; public RigJson rig; }
    [Serializable] public class FormsIndexJson { [Serializable] public class Item { public string key, name, file; } public Item[] forms; }

    public static class GenomeKeys
    {
        /// Same key as tools/export-unity.ts (one per distinct look).
        public static string Key(Genome g)
        {
            string s(PartSlot p) => $"{g[p]}{g.variant[(int)p]}";
            return $"{s(PartSlot.body)}-{s(PartSlot.head)}-{s(PartSlot.legs)}-{s(PartSlot.tail)}-{s(PartSlot.back)}-{g.eyes}-{g.pattern}-{g.paletteBase}{g.shade}{g.paletteAccent}-{g.mutation}";
        }
        /// Key of the body plan only (colours and mutation are applied at runtime by the tint mask).
        public static string ShapeKey(Genome g)
        {
            string s(PartSlot p) => $"{g[p]}{g.variant[(int)p]}";
            return $"{s(PartSlot.body)}-{s(PartSlot.head)}-{s(PartSlot.legs)}-{s(PartSlot.tail)}-{s(PartSlot.back)}-{g.eyes}-{g.pattern}";
        }

        /// Assembles the rig of ANY genome from the part library (mirror of genomeRig in packages/art/src/modular/build.ts).
        public static RigJson Assemble(CatalogJson cat, Genome g)
        {
            LibraryEntry E(string slot, string label)
            {
                foreach (var e in cat.library) if (e.slot == slot && e.label == label) return e;
                throw new ArgumentException($"Missing library entry {slot}/{label} — re-run tools/export-unity.ts");
            }
            string L(PartSlot p) => $"{g[p]}_{g.variant[(int)p]}";
            var legs = E("legs", L(PartSlot.legs));
            var parts = new List<PartJson>();
            foreach (var step in cat.assembly.order)
            {
                var e = step switch
                {
                    "shared" => E("shared", "chispin"),
                    "eyes" => E("eyes", g.eyes),
                    "pattern" => E("pattern", g.pattern),
                    "legs" => legs,
                    _ => E(step, L((PartSlot)Enum.Parse(typeof(PartSlot), step))),
                };
                parts.AddRange(e.parts);
            }
            // Unique ids, as the web compiler does.
            var seen = new Dictionary<string, int>();
            var unique = new List<PartJson>();
            foreach (var p in parts)
            {
                seen.TryGetValue(p.id, out int n); seen[p.id] = n + 1;
                var c = (PartJson)UnityEngine.JsonUtility.FromJson(UnityEngine.JsonUtility.ToJson(p), typeof(PartJson));
                if (n > 0) c.id = $"{p.id}_{n}";
                unique.Add(c);
            }
            var bones = new List<BoneJson>();
            foreach (var b in cat.skeleton.bones)
                bones.Add(new BoneJson { id = b.id, parent = b.parent, x = b.x, y = legs.@float && b.id == cat.assembly.floatBone ? b.y - cat.assembly.floatBodyLift : b.y, rot = b.rot });
            return new RigJson { id = "genome", bones = bones.ToArray(), parts = unique.ToArray(), secondary = cat.skeleton.secondary, breathBone = cat.skeleton.breathBone, eyeBones = cat.skeleton.eyeBones };
        }
    }
}
